def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        counts = Counter(row)
        if len(counts) < 2:
            continue
        least = min(counts.values())
        for c, value in enumerate(row):
            if counts[value] == least:
                out[r][c] = 1
    return out
